var HCUST = ssGet("yqi_hcust") || "", HMSG = "", HPLAN = "", HFILT = "", HANIM = true;
function pc(a, b){ return b ? (Math.round(a / b * 1000) / 10) + "%" : "—"; }
function dmy(d){ return d && d.length >= 10 ? d.slice(8, 10) + "-" + d.slice(5, 7) + "-" + d.slice(2, 4) : "—"; }
function hTable(head, rows){ return '<table><tr>' + head.map(function(h){ return '<th' + (h[1] ? ' class="hide-m"' : '') + '>' + h[0] + '</th>'; }).join("") + '</tr>' + rows.join("") + '</table>'; }
function barc(a, b){ return b ? '<div style="display:flex;align-items:center;gap:6px"><div class="bar"><i style="width:' + Math.round(a / b * 100) + '%"></i></div>' + pc(a, b) + '</div>' : '—'; }
var PST = {pass: "Passed", repass: "Passed after re-inspection", fail: "Failed", pend: "Not inspected yet", reins: "Re-inspection", all: "All inspections"};
function tip(t){ return ' data-tip="' + esc(t) + '"'; }
function kpi(t, v, ac, sub, tp, go){ return '<div class="k" style="--ac:' + (ac || "#5BA32A") + '"' + (tp ? tip(tp) : "") + (go ? ' data-go="' + go + '"' : "") + '><span data-ek="k:' + esc(t) + '">' + t + '</span><b>' + v + '</b><i>' + sub + '</i></div>'; }
function lotTip(q){
  var s = q.cust + " · " + (q.kind === "plan" ? "Shipping plan " + q.id : q.lbl) + "\n" + dmy(q.date) + (q.last && q.last !== q.date ? " → " + dmy(q.last) : "") + " · " + PST[q.first === "reins" ? "reins" : q.final];
  if(q.kind === "plan") s += "\n" + q.n + " articles · " + q.p1 + " passed 1st go" + (q.re ? " · " + q.re + " re-inspected" : "") + (q.bad ? " · " + q.bad + " failed" : "") + (q.ni ? " · " + q.ni + " not inspected" : "");
  if(q.hist) s += "\n" + q.hist.map(function(r){ return dmy(r.date) + " " + r.result + (r.major != null && r.sample ? " (" + r.major + "/" + r.sample + ")" : ""); }).join("\n");
  if(q.kind === "is"){ if(q.art) s += "\n" + q.art; if(q.sample) s += "\nSample " + q.sample + " · major " + q.major; }
  var d = Object.keys(q.dl || {}).sort(function(a, b){ return q.dl[b] - q.dl[a]; }).slice(0, 4); if(d.length) s += "\nDefects: " + d.map(function(k){ return k + " " + q.dl[k]; }).join(", ");
  return s + "\nClick for details";
}
function ring(segs, total){
  var R = 70, C = 2 * Math.PI * R, off = 0, s = '<svg viewBox="0 0 170 170"><circle cx="85" cy="85" r="' + R + '" fill="none" stroke="rgba(255,255,255,.12)" stroke-width="16"/>';
  segs.forEach(function(g){ if(!g.v || !total) return; var L = g.v / total * C; s += '<circle cx="85" cy="85" r="' + R + '" fill="none" stroke="' + g.c + '" stroke-width="16" stroke-dasharray="' + L + ' ' + (C - L) + '" stroke-dashoffset="' + (-off) + '" stroke-linecap="butt"><title>' + esc(g.t + ": " + g.v) + '</title></circle>'; off += L; });
  return s + '</svg>';
}
function heroLeaves(){ var s = '<div class="hlv">'; for(var i = 0; i < 7; i++) s += '<img src="' + LEAF + '" alt="" style="left:' + (8 + i * 13) + '%;width:' + (10 + (i * 5) % 12) + 'px;animation-duration:' + (11 + (i * 4) % 9) + 's;animation-delay:' + (-i * 2.3) + 's">'; return s + '</div>'; }
