  var own = YQE.ownNode(el), box = YQE.boxOf(el, h), cur = own ? own.nodeValue.trim() : "", p = document.createElement("div"); p.id = "yqHx";
  p.innerHTML = '<div class="hxh"><b>Edit this item</b><button data-x="x" aria-label="Close">✕</button></div>' + (own ? '<label>Text</label><input id="yqHxI" value="' + esc(cur).replace(/"/g, "&quot;") + '"><button class="s" data-x="t">Change text</button>' : '<div class="hxn">This item has no text of its own. You can hide or delete it.</div>') +
    '<div class="hxr"><button data-x="h">Hide item</button>' + (box ? '<button data-x="hb">Hide whole box</button>' : '') + '</div><div class="hxr"><button class="d" data-x="d">Delete item</button>' + (box ? '<button class="d" data-x="db">Delete whole box</button>' : '') + '</div><div class="hxn">Press Save in the bar below to keep the changes.</div>';
  document.body.appendChild(p);
