  var b = document.createElement("div"); b.id = "yqEdBar"; b.innerHTML = '<span>Editing: tap dashed text to change it. Tap any other box, heading or number to change, hide or delete it. Tap a logo to change the picture.</span><button class="s" id="yqEdS">Save</button><button id="yqEdC">Cancel</button><button id="yqEdR">Reset all</button>'; document.body.appendChild(b);
