  fi.onchange = function(){ var f = fi.files[0]; fi.value = ""; if(!f || !tgt) return; imgToData(f, /^logo:/.test(tgt.dataset.ei) ? 160 : 600).then(function(u){ HPEND[tgt.dataset.ei] = u; if(tgt.tagName === "IMG") tgt.src = u; else tgt.innerHTML = '<img src="' + u + '" alt="">'; }).catch(function(){ yqAsk("This picture could not be read."); }); };
  h.__edc = function(e){ if(!HEDIT) return; var im = e.target.closest("[data-ei]"); if(im){ e.preventDefault(); e.stopPropagation(); tgt = im; fi.click(); return; } if(e.target.closest("[data-ek]")){ e.stopPropagation(); if(e.target.closest("button,a")) e.preventDefault(); return; } e.preventDefault(); e.stopPropagation(); if(e.target !== h && h.contains(e.target)) hxOpen(e.target.closest("svg") && e.target.closest("svg").parentElement !== h ? e.target.closest("svg") : e.target); };
  h.addEventListener("click", h.__edc, true);
