  var WLABELS = {cust: "Customer switcher", inspsum: "Inspection Summary", capa: "CAPA tracker", insp: "Inspections", repack: "Repacking", report: "Today's report", upload: "Upload inspections"};
  var EXTRA_LABELS = {x_reinsp: "Re-inspections", x_wastage: "Wastage %", x_intfail: "Internal failed"};
  var ord = dOrdApply(Object.keys(WLABELS).concat(Object.keys(EXTRA_LABELS)));
  var extraOn = (HDASH.extra || []).slice(), th = Object.assign({ac: "", font: "sys"}, HDASH.theme || {}), acCleared = false;
  function rowHtml(id){ var isExtra = !!EXTRA_LABELS[id], label = WLABELS[id] || EXTRA_LABELS[id], on = isExtra ? extraOn.indexOf(id) >= 0 : true;
    return '<li draggable="true" data-id="' + id + '" class="' + (on ? "" : "off") + '"><span class="gr">⠿</span>' + (isExtra ? '<input type="checkbox" data-tgl="' + id + '"' + (on ? " checked" : "") + '>' : '<span style="width:18px;text-align:center">🔒</span>') + '<b>' + esc(label) + '</b><span class="tg">' + (isExtra ? "optional" : "always on") + '</span><span class="ar"><button type="button" data-up="' + id + '" title="Move up">▲</button><button type="button" data-dn="' + id + '" title="Move down">▼</button></span></li>'; }
  var fontOpts = Object.keys(HFONTS).map(function(k){ return '<option value="' + k + '"' + (th.font === k ? " selected" : "") + '>' + HFONTS[k][0] + '</option>'; }).join("");
  var body = '<div class="dcnote">Drag the ⠿ handle, or use ▲▼, to reorder the Home page widgets. Tick an optional widget to add it. Saved for everyone who opens YQI.</div><ul id="yqDOrd" class="dord">' + ord.map(rowHtml).join("") + '</ul>' +
    '<div class="dch"><b>Colour &amp; font</b><span>changes the Home page only</span></div>' +
    '<div class="dcrow"><label><input type="color" id="yqDAc" value="' + (th.ac || "#5BA32A") + '">Accent colour</label><label>Font <select id="yqDFt">' + fontOpts + '</select></label><button type="button" class="dcbtn" id="yqDAcClr">Reset colour</button></div>' +
    '<div class="dcrow" style="margin-top:18px"><button type="button" class="dcbtn g" id="yqDSave">✓ Save for everyone</button><button type="button" class="dcbtn" id="yqDReset">Reset all</button></div>';
  yqSheet("🧩 Customize dashboard", body);
