// ---------- today's report → WhatsApp (one tap) ----------
function dailyText(){ var lots = (window.YQLOTS || []), td = new Date().toISOString().slice(0, 10), y = new Date(Date.now() - 864e5).toISOString().slice(0, 10);
  var day = lots.reduce(function(m, l){ return l.date && l.date <= td && l.date > m ? l.date : m; }, "") || td, L = lots.filter(function(l){ return l.date === day; });
  var pass = L.filter(function(l){ return l.final === "pass" || l.final === "repass"; }).length, fail = L.filter(function(l){ return l.final === "fail"; }).length, re = L.filter(function(l){ return l.final === "repass" || l.first === "reins"; }).length;
  var by = {}; L.forEach(function(l){ var c = by[l.cust] = by[l.cust] || {n: 0, f: 0}; c.n++; if(l.final === "fail") c.f++; });
  var dl = {}; L.forEach(function(l){ Object.keys(l.dl || {}).forEach(function(k){ dl[k] = (dl[k] || 0) + l.dl[k]; }); });
  var top = Object.keys(dl).sort(function(a, b){ return dl[b] - dl[a]; }).slice(0, 5);
  var t = "*YQI daily quality report*\n" + day + "\n\nInspections: " + L.length + "\nPassed: " + pass + "   Failed: " + fail + (re ? "   Re-inspection: " + re : "") + (L.length ? "\nPass rate: " + Math.round(pass * 100 / L.length) + "%" : "") + "\n";
  if(Object.keys(by).length) t += "\n*By customer*\n" + Object.keys(by).map(function(c){ return "• " + c + ": " + by[c].n + (by[c].f ? " (" + by[c].f + " failed)" : ""); }).join("\n") + "\n";
  var fl = L.filter(function(l){ return l.final === "fail"; }); if(fl.length) t += "\n*Failed lots*\n" + fl.slice(0, 10).map(function(l){ return "• " + l.cust + " " + l.lbl + (l.art ? " · " + l.art : "") + (l.unit ? " · " + l.unit : ""); }).join("\n") + "\n";
  if(top.length) t += "\n*Top defects*\n" + top.map(function(k){ return "• " + k + ": " + dl[k]; }).join("\n") + "\n";
  return t + "\n_From YQI · Yunus Quality Intelligence_"; }
function shareDaily(){ var t = dailyText(); var o = yqSheet("Today's report", '<pre class="caPre">' + esc(t) + '</pre><div class="caAct"><button class="caNew" id="yqWa">Send on WhatsApp</button><button class="caGh" id="yqCp">Copy</button></div>');
  $("yqWa").onclick = function(){ window.open("https://wa.me/?text=" + encodeURIComponent(t), "_blank"); };
  $("yqCp").onclick = function(){ try{ navigator.clipboard.writeText(t); this.textContent = "Copied ✓"; }catch(e){} }; }

